<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Toko Online</title><style>body{font-family:Arial;background:#f3f4f6;padding:2rem}main{max-width:70rem;margin:auto}.top{display:flex;justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:1rem}.card{background:#fff;padding:1rem;border-radius:.6rem}button{padding:.6rem;background:#2563eb;color:#fff;border:0;border-radius:.3rem}</style></head><body><main><div class="top"><h1>Toko Online</h1><nav><a href="{{ route('cart.index') }}">Keranjang ({{ array_sum(session('cart', [])) }})</a> | <a href="{{ route('orders.index') }}">Riwayat pesanan</a> | @guest<a href="{{ route('login') }}">Login</a>@else<form style="display:inline" method="POST" action="{{ route('logout') }}">@csrf<button>Logout</button></form>@endguest</nav></div><h2>Daftar Barang</h2><div class="grid">@foreach($products as $product)<article class="card"><div style="font-size:2.5rem">📦</div><h3>{{ $product->name }}</h3><p>{{ $product->description }}</p><strong>Rp {{ number_format($product->price,0,',','.') }}</strong><p>Stok: {{ $product->stock }}</p>@auth @if($product->stock)<form method="POST" action="{{ route('cart.add',$product) }}">@csrf<button>Tambah ke keranjang</button></form>@endif @else<p><a href="{{ route('login') }}">Login untuk membeli</a></p>@endauth</article>@endforeach</div></main></body></html>
